(async()=>{
window.audit={requests:[]};const originalFetch=window.fetch;window.fetch=(...args)=>{const url=String(args[0]);if(url.includes('/api/assistant-ai'))throw Error('Unexpected Gemini request');if(url.includes('/api/minimax-ai')&&args[1]?.method==='POST')audit.requests.push({url,body:JSON.parse(args[1].body)});return originalFetch(...args)};
audit.store=(await import('/src/studio/store.ts')).useStudio;
audit.jobId=audit.store.getState().job.id;
(await import('/src/studio/assistant/provider.ts')).useAssistantProvider.getState().setProvider('minimax');
(await import('/src/studio/assistant/permissions.ts')).usePermissions.getState().setMode('auto');
localStorage.setItem('xray:assistant-execution-budget:v1',JSON.stringify({maxRounds:16,maxToolCalls:48,maxOutputTokens:8192,timeoutMs:90000,contextTokens:300000}));
audit.file=await (await import('/src/studio/assistant/attachmentFiles.ts')).storeAssistantFile(audit.jobId,new File(['Audit fixture: the room is called Willow Study. Requested illustrative dimensions are 6000 mm by 4000 mm. This is a test brief, not a surveyed drawing.'],'audit-brief.txt',{type:'text/plain'}));
document.querySelector('.live-assistant-launcher')?.click();
return {project:audit.jobId,file:audit.file};
})()
